#!/usr/bin/env bash
# ATS-213 evidence collector -- the WBS row and the checksum manifest.
#
# The WBS row is written by tools/update_wbs_ats213.py, and the row it
# produces is READ BACK from the workbook (not from the script's own
# variables): a script that reports what it intended to write proves
# nothing about what the workbook holds.
#
# The checksum manifest is regenerated by tools/update_checksums.py, which
# reads the git blobs -- so it must run AFTER the content is committed. When
# the tree is dirty the generator stops with a message; that is reported, not
# hidden.
#
# Usage: bash tools/ats213-probes/collect-wbs-and-checksums.sh
set -u

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT" || exit 1

export PYTHONUTF8=1
export PYTHONIOENCODING=utf-8
export TEMP="${TEMP_OVERRIDE:-D:/hermes-multica/home/cache/scratch}"
export TMP="$TEMP"

printf -- '--- 1. the WBS row update ---\n'
python tools/update_wbs_ats213.py
printf 'the updater exit code: %s\n' "$?"

printf '\n%s\n' '--- 2. the WBS row read back from the workbook ---'
python - <<'PY'
import sys
sys.path.insert(0, 'tools')
from wbs_common import read_parts, sheet_cells, SHEET1, SHEET2

rows = sheet_cells(read_parts(), SHEET2)
hit = [(rid, row) for rid, row in sorted(rows.items()) if row.get('A') == 'ATS-213']
if not hit:
    print('FAIL: the ATS-213 row was not found')
    raise SystemExit(1)
rid, row = hit[0]
print(f'row            : {rid}')
print(f'状态            : {row.get("N")}')
print(f'完成率          : {row.get("O")}')
print(f'剩余人日        : {row.get("P")}')
print(f'估算人日        : {row.get("K")}')
print(f'验证方式        : {row.get("Q")}')
print(f'关联要件        : {row.get("R")}')
note = row.get('T', '')
print(f'备注长度        : {len(note)}')
print(f'【ATS-213】×     : {note.count("【ATS-213】")}')
ok = (row.get('N') == '待审核' and row.get('O') == '1' and row.get('P') == '0'
      and note.count('【ATS-213】') == 1)
print(f'RESULT: {"OK" if ok else "MISMATCH"} -- the ATS-213 row reads 状态=待审核 完成率=1 剩余人日=0 marker×1')
if not ok:
    raise SystemExit(1)
PY
printf 'the read-back exit code: %s\n' "$?"

printf '\n%s\n' '--- 3. the overview totals (recomputed from the sheet) ---'
python - <<'PY'
import sys
sys.path.insert(0, 'tools')
from wbs_common import read_parts, sheet_cells, SHEET1

s1 = sheet_cells(read_parts(), SHEET1)
for rid, label in ((8, '已完成 count'), (9, '完成率'), (10, '剩余人日')):
    print(f'B{rid} {label}: {s1.get(rid, {}).get("B")}')
PY

printf '\n%s\n' '--- 4. the checksum manifest ---'
python tools/update_checksums.py
printf 'update_checksums exit code: %s\n' "$?"
python tools/verify_checksums.py
printf 'verify_checksums exit code: %s\n' "$?"
